$j$[{"lang":"🇺🇸 EN","text":"Good vibes (nice feel/aesthetic)"},{"lang":"🇯🇵 JA","text":"ヌジョッ(いい雰囲気)"},{"lang":"🇨🇳 ZH","text":"感觉真好(氛围赞)"},{"lang":"🇻🇳 VI","text":"Vibe tốt (cảm giác đẹp)"},{"lang":"🇪🇸 ES","text":"Buena vibra (ambiente lindo)"},{"lang":"🇩🇪 DE","text":"Gute Stimmung (schönes Gefühl)"}]$j$::jsonb),

('132', 'ㄱㄱ', 'Geu-Geu', 'consonant', '''고고(go go)''의 초성만 딴 말, 하자는 뜻',
$j${"en":"Initials for 'go go' — let's do it","ja":"「ゴーゴー(go go)」の初声、やろうという意味","es":"Iniciales de 'go go' — vamos a hacerlo","vi":"Chữ cái đầu của 'go go' — nghĩa là làm thôi","de":"Initialen für 'go go' — lass uns loslegen"}$j$::jsonb,
'[그-그]',
$j$[{"type":"감탄사","examples":[{"kor":"우리 이제 나갈까? ㄱㄱ","eng":"Should we head out now? Let's go.","ja":"そろそろ出よっか?ㄱㄱ","es":"¿Salimos ya? Vamos.","vi":"Mình đi giờ nhé? Đi thôi.","de":"Sollen wir jetzt losgehen? Auf geht's."}],"definition":"영어 'go'에서 온 '고고'의 초성만 딴 초성체. 무언가를 하자는 의지나 제안을 나타낼 때 쓴다.","definition_i18n":{"en":"A choseong-che (initial-consonant-only) form of '고고', from the English 'go'. Used to express willingness or a suggestion to do something.","ja":"英語の『go』から来た「고고」の初声(子音字)だけを取った初声体。何かをしようという意志や提案を表すときに使う。","es":"Una forma choseong-che (solo consonantes iniciales) de '고고', del inglés 'go'. Se usa para expresar disposición o proponer hacer algo.","vi":"Một dạng choseong-che (chỉ lấy phụ âm đầu) của '고고', từ tiếng Anh 'go'. Dùng để thể hiện ý muốn hoặc đề nghị làm gì đó.","de":"Eine Choseong-che-Form (nur Anfangskonsonanten) von '고고', vom englischen 'go'. Wird verwendet, um Bereitschaft auszudrücken oder etwas vorzuschlagen."}}]$j$::jsonb,
'초성체(자음자만 따서 쓰는 인터넷 표기법)의 하나로, ''고고''를 초성 ''ㄱㄱ''으로 줄여 쓰기 시작한 것이 온라인 채팅·게임에서 굳어졌다.',
$j${"en":"One of many 초성체 (initial-consonant writing) forms, where '고고' got shortened to the consonants 'ㄱㄱ' and the habit stuck in online chats and gaming.","ja":"초성체(初声だけを書く表記法)の一つで、「고고」を子音字「ㄱㄱ」に縮めて使うようになったのがオンラインチャットやゲームで定着した。","es":"Una de las muchas formas del 초성체 (escritura con solo consonantes iniciales), donde '고고' se abrevió a las consonantes 'ㄱㄱ' y el hábito se afianzó en chats en línea y videojuegos.","vi":"Một trong nhiều dạng 초성체 (chỉ viết phụ âm đầu), khi '고고' được rút gọn thành phụ âm 'ㄱㄱ' và thói quen này bám rễ trong chat trực tuyến và game.","de":"Eine von vielen 초성체-Formen (Schreibweise mit nur Anfangskonsonanten), bei der '고고' zu den Konsonanten 'ㄱㄱ' verkürzt wurde und sich die Gewohnheit in Online-Chats und beim Gaming festsetzte."}$j$::jsonb,
'같이 뭘 하자고 제안할 때, 또는 준비됐냐는 물음에 동의할 때 짧게 ''ㄱㄱ''이라고 답한다.',
$j${"en":"Used to suggest doing something together, or to agree when asked if you're ready — a short 'ㄱㄱ'.","ja":"何かを一緒にしようと誘うとき、または準備できたか聞かれて同意するときに短く「ㄱㄱ」と答える。","es":"Se usa para proponer hacer algo juntos, o para asentir cuando te preguntan si estás listo, con un breve 'ㄱㄱ'.","vi":"Dùng để rủ làm gì đó cùng nhau, hoặc đồng ý khi được hỏi đã sẵn sàng chưa — đáp gọn 'ㄱㄱ'.","de":"Wird verwendet, um vorzuschlagen, etwas gemeinsam zu tun, oder um zuzustimmen, wenn gefragt wird, ob man bereit ist — kurz 'ㄱㄱ'."}$j$::jsonb,
